let AllDeviceNames = DeviceInfo | distinct DeviceId, DeviceName;
let DeviceEventSummary = DeviceEvents | summarize count() by DeviceId, Type, bin(TimeGenerated,1d);
let DeviceNetworkEventsSummary = DeviceNetworkEvents | summarize count() by DeviceId,Type, bin(TimeGenerated,1d);
let DeviceNetworkInfoSummary = DeviceNetworkInfo | summarize count() by DeviceId,Type, bin(TimeGenerated,1d);
let DeviceLogonEventsSummary = DeviceLogonEvents | summarize count() by DeviceId,Type, bin(TimeGenerated,1d);
let DeviceRegistryEventsSummary = DeviceRegistryEvents | summarize count() by DeviceId,Type, bin(TimeGenerated,1d);
let DeviceProcessEventsSummary = DeviceProcessEvents | summarize count() by DeviceId,Type, bin(TimeGenerated,1d);
(DeviceEventSummary
| union DeviceNetworkEventsSummary,
DeviceNetworkEventsSummary,
DeviceNetworkInfoSummary,
DeviceLogonEventsSummary,
DeviceRegistryEventsSummary,
DeviceProcessEventsSummary)
| join kind=inner ( 
AllDeviceNames
)
on $left.DeviceId == $right.DeviceId
| project-reorder Type, TimeGenerated, count_
//| project-away DeviceId, DeviceId1

//This query shows the source of the AV detections (e.g., the website the file was downloaded from etc.)
//
//Get the list of AV detections
let avDetections =
DeviceEvents
| where ActionType == "AntivirusDetection" and isnotempty(MD5)
| extend ParsedFields=parse_json(AdditionalFields)
| project Timestamp, DeviceName, ThreatName=tostring(ParsedFields.ThreatName), FileName, FolderPath, MD5;
//Get a list of file creations
let fileCreations =
DeviceFileEvents 
| where (isnotempty(FileOriginReferrerUrl) or isnotempty(FileOriginUrl)) and isnotempty(MD5)
| project MD5, FileOriginUrl, FileOriginReferrerUrl, InitiatingProcessFileName, InitiatingProcessParentFileName;
//Join the file creations and AV detections on the MD5 of the file
avDetections | join kind=inner (fileCreations) on MD5
| project-away MD51 //Remove the duplicated MD5 field
| sort by Timestamp desc

//This query make a best-guess detection regarding which removable media device caused an AV detection
//The query is best run over 30 days to get the full USB history
//
//Get a list of USB AV detections. This assumes any path not beginning with C is a removable/USB device
let usbDetections =
    DeviceEvents
    | where ActionType == "AntivirusDetection" and FolderPath !startswith "c" and FolderPath matches regex "^[A-Za-z]{1}"
    | extend ParsedFields=parse_json(AdditionalFields)
    | project DetectionTime=Timestamp, DeviceName, ThreatName=tostring(ParsedFields.ThreatName), FileName, FolderPath;
//Get a list of USB disk drive connections, grouped by computer name and DeviceID
let usbConnections = 
    DeviceEvents
    | where ActionType == "PnpDeviceConnected"
    | extend parsed=parse_json(AdditionalFields)
    | project Timestamp, DeviceName, DeviceId=tostring(parsed.DeviceId), ClassName=tostring(parsed.ClassName)
    | where ClassName == "DiskDrive"
    | summarize UsbFirstSeen=min(Timestamp), UsbLastSeen=max(Timestamp) by DeviceId, DeviceName;
//Join USB AV detections and connections, where the detection occurs after the USB has been plugged in
usbDetections | join kind=inner (usbConnections) on DeviceName | where DetectionTime > UsbFirstSeen and DetectionTime < UsbLastSeen
| project DetectionTime, DeviceName, ThreatName, FileName, FolderPath, DeviceId, UsbFirstSeen, UsbLastSeen
| sort by DetectionTime desc

// This query looks for Tor client, or for a common Tor plugin called Meek.
// We query for active Tor connections, but could have alternatively looked for active Tor runs (ProcessCreateEvents) or Tor downloads (DeviceFileEvents)
// To read more about this technique, see:
// Tor: https://attack.mitre.org/wiki/Software/S0183#Techniques_Used
// Meek plugin: https://attack.mitre.org/wiki/Software/S0175
// Multi-hop proxy technique: https://attack.mitre.org/wiki/Technique/T1188
// Tags: #Tor, #MultiHopProxy, #CnC
DeviceNetworkEvents  
| where Timestamp < ago(3d) and InitiatingProcessFileName in~ ("tor.exe", "meek-client.exe")
// Returns MD5 hashes of files used by Tor, to enable you to block them.
// We count how prevalent each file is (by machines) and show examples for some of them (up to 5 machine names per hash).
| summarize MachineCount=dcount(DeviceName), MachineNames=makeset(DeviceName, 5) by InitiatingProcessMD5
| order by MachineCount desc

//This query visualises total emails with Phish detections summarizing the data by intent of the message.
// Microsoft Defender for Office 365 LLM analysis is analyzing email messages to understand the intent of the messages. These threat classifications are then used in filtering decisions.
//The comment in the query excludes deliveries to the SecOps Mailbox and by the Phish Simulation system. Remove the "//" to apply the exclusion.
EmailEvents 
| where OrgLevelPolicy != "Phishing simulation" and OrgLevelPolicy != "SecOps Mailbox"
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| where ThreatTypes has 'Phish' and ThreatClassification  has_any("Business intelligence","Contact establishment","Gift card","Invoice","Payroll","PII gathering","Task")
| summarize count() by ThreatClassification
| sort by count_ desc

//This query calculates the effectiveness of spam detections without edge data.
let minTime = toscalar(EmailEvents | summarize min(Timestamp));
let maxTime = toscalar(EmailEvents | summarize max(Timestamp));
// baseQuery _FN_Admin_Submissions_SPM
let _FN_Admin_Submissions_SPM = toscalar(
CloudAppEvents
| where Timestamp between (minTime .. maxTime)
| where ActionType == "AdminSubmissionSubmitted"
| extend SubmissionType = tostring((parse_json(RawEventData)).SubmissionType)
| extend NetworkMessageId = tostring((parse_json(RawEventData)).ObjectId)
| where SubmissionType in ("0")
| summarize count()
);
// baseQuery _FN_ZAP_Successful_Spam
let _FN_ZAP_Successful_Spam = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and ActionType == "Spam ZAP" and ActionResult == "Success" and Timestamp between (minTime .. maxTime)
| summarize count()
    //Take all our Spam ZAP, and count how many messages we missed and successfully cleaned up.
);
// baseQuery _FN_ZAP_Unsuccessful_Spam
let _FN_ZAP_Unsuccessful_Spam = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and ActionType == "Spam ZAP" and ActionResult != "Success" and Timestamp between (minTime .. maxTime)
| summarize count()
//Take all our Spam ZAP, and count how many messages we failed to clean up due to error or users/admins/API vendors getting to the message first.
);
// baseQuery _SPAM_ZAP_FP
let _SPAM_ZAP_FP = toscalar(
EmailPostDeliveryEvents
| where ActionTrigger == "SpecialAction" and Action has_any ("Redelivery","Reprocessed") and Timestamp between (minTime .. maxTime)
| join kind=leftsemi (
            EmailEvents
            | where Timestamp between (minTime ..maxTime )
            | where ThreatTypes contains "Spam"
            | project NetworkMessageId, ThreatTypes)
            on NetworkMessageId
| summarize count()
// count all the FPs which were originally Spam, and when we TT'd them were not so we can subtract that from our mailfow catch, and therefore the total true bad.
);
// baseQuery _Spam_Mailflow
let _Spam_Mailflow = toscalar(
EmailEvents
| where EmailDirection == "Inbound" and ThreatTypes == "Spam" and Timestamp between (minTime .. maxTime)
| extend Key = strcat(NetworkMessageId , '-', RecipientEmailAddress) 
| summarize arg_max(Timestamp, *) by Key
| summarize count()
// Get all the mailflow detected as SPM, then count all the NMIDs (not distinct)
);
print
Effectiveness_PostDelivery = abs(round(((toreal(toscalar(_FN_Admin_Submissions_SPM))+toreal(toscalar(_FN_ZAP_Unsuccessful_Spam)))/(toreal(toscalar(_Spam_Mailflow))+toreal(toscalar(_FN_ZAP_Successful_Spam))+toreal(toscalar(_FN_ZAP_Unsuccessful_Spam))+toreal(toscalar(_FN_Admin_Submissions_SPM))-toreal(toscalar(_SPAM_ZAP_FP)))*100-100),2))

