//This query lists external email senders seen for the first time in the selected period (most recent first), surfacing new/first-contact senders. In tenants with longer history this highlights genuinely new relationships - a common precursor to BEC and supply-chain attacks.
// TIP: to hide your own accepted domains, uncomment the ExcludeDomains line and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","fabrikam.com"]);
EmailEvents
| where EmailDirection == "Inbound"
| extend SenderDomain = tostring(split(SenderFromAddress, "@")[1])
| where isnotempty(SenderFromAddress)
//| where SenderDomain !in~ (ExcludeDomains)
| summarize FirstSeen=min(Timestamp), Messages=count(), ThreatMessages=countif(isnotempty(ThreatTypes)) by SenderFromAddress, SenderDomain
| top 20 by FirstSeen desc
| project ['Sender']=SenderFromAddress, ['Sender Domain']=SenderDomain, ['First Seen']=FirstSeen, Messages, ['Threat Messages']=ThreatMessages

//This query lists external sender domains seen for the first time in the selected period that already carried threats, ranked by most-recently first seen. A brand-new domain sending threats to your users is a strong early-warning signal for phishing and BEC.
// TIP: to hide your own accepted domains, uncomment the ExcludeDomains line and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","fabrikam.com"]);
EmailEvents
| where EmailDirection == "Inbound"
| extend SenderDomain = tostring(split(SenderFromAddress, "@")[1])
| where isnotempty(SenderDomain)
//| where SenderDomain !in~ (ExcludeDomains)
| summarize FirstSeen=min(Timestamp), LastSeen=max(Timestamp), Messages=count(), Senders=dcount(SenderFromAddress), Recipients=dcount(RecipientEmailAddress), ThreatMessages=countif(isnotempty(ThreatTypes)) by SenderDomain
| where ThreatMessages > 0
| top 20 by FirstSeen desc
| project ['Sender Domain']=SenderDomain, ['First Seen']=FirstSeen, Messages, Senders, Recipients, ['Threat Messages']=ThreatMessages, ['Last Seen']=LastSeen

//This query visualises where URL's have been scanned identified from various locations in emails
EmailUrlInfo
| summarize  count() by UrlLocation

//This query visualises where URL clicks scanned by the Workload the click happened from
UrlClickEvents
| summarize  count() by Workload

//This query lists the top 10 senders whose Microsoft Teams messages triggered a URL safety-tip warning for the selected period, with each sender's total Teams messages and the share that carried a warning. Messages are de-duplicated to the latest record per message.
let dedup = MessageEvents | summarize arg_max(Timestamp, *) by TeamsMessageId;
let totals = dedup | summarize TotalMessages = count() by SenderEmailAddress;
dedup
| where SafetyTip == "URLMessageWarning"
| summarize WarningMessages = count() by SenderEmailAddress
| join kind=leftouter (totals) on SenderEmailAddress
| extend WarningPct = round(100.0 * WarningMessages / TotalMessages, 1)
| top 10 by WarningMessages
| project ['Sender']=SenderEmailAddress, ['Warning Messages']=WarningMessages, ['Total Messages']=TotalMessages, ['Warning %']=WarningPct

//This query lists the top 10 URL domains appearing in Microsoft Teams messages that triggered a URL safety-tip warning, with the domain's total message appearances and the share that carried a warning.
let warned = MessageEvents | where SafetyTip == "URLMessageWarning" | distinct TeamsMessageId;
let totals = MessageUrlInfo | where isnotempty(UrlDomain) | summarize TotalMessages = dcount(TeamsMessageId) by UrlDomain;
MessageUrlInfo
| where TeamsMessageId in (warned)
| summarize WarningMessages = dcount(TeamsMessageId) by UrlDomain
| join kind=leftouter (totals) on UrlDomain
| extend WarningPct = round(100.0 * WarningMessages / TotalMessages, 1)
| top 10 by WarningMessages
| project ['URL Domain']=UrlDomain, ['Warning Messages']=WarningMessages, ['Total Messages']=TotalMessages, ['Warning %']=WarningPct

//This query lists external Microsoft Teams senders by the date they were first seen in the selected period, surfacing recent first-contact senders. Messages are de-duplicated to the latest record per message. In tenants with longer history this highlights genuinely new senders.
// TIP: IsExternalThread may still surface senders from your own accepted domains. To hide them,
// uncomment the ExcludeDomains line below (add your tenant domains) and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","contoso.com"]);
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| where IsExternalThread == true
//| where tostring(split(SenderEmailAddress, "@")[1]) !in~ (ExcludeDomains)
| summarize FirstSeen = min(Timestamp), Messages = count(), ThreatMessages = countif(isnotempty(ThreatTypes)) by SenderEmailAddress
| top 10 by FirstSeen desc
| project ['Sender']=SenderEmailAddress, ['First Seen']=FirstSeen, ['Messages']=Messages, ['Threat Messages']=ThreatMessages

//This query ranks external sender domains in Microsoft Teams by threat volume for the selected period, split by conversation type (1:1 chat, group chat, channel), with threat-type breakdown, threat rate, and a count of messages carrying low-reputation URL TLDs. Messages are de-duplicated to the latest record per message. New, 1:1-skewed, or high-threat-rate domains are the anomalies to review.
// TIP: IsExternalThread may still surface your own accepted domains. To hide them, uncomment the
// ExcludeDomains line below (add your tenant domains) and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","contoso.com"]);
let suspTlds = dynamic(["top","xyz","click","link","shop","online","site","live","icu","cyou","sbs","rest","quest","cfd","bond","buzz","fun","space","monster","work","tk","ml","ga","cf","gq","dev","app","zip","mov","info","win","loan","men","stream","country"]);
let suspUrlMsgs = MessageUrlInfo
    | where isnotempty(UrlDomain)
    | extend Tld = tostring(split(UrlDomain, ".")[-1])
    | where Tld in (suspTlds)
    | distinct TeamsMessageId;
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| where IsExternalThread == true
| extend SenderDomain = tostring(split(SenderEmailAddress, "@")[1])
| where isnotempty(SenderDomain)
//| where SenderDomain !in~ (ExcludeDomains)
| extend ConvType = case(isnotempty(GroupId), "Channel", array_length(todynamic(RecipientDetails)) > 1, "Group chat", "1:1 chat")
| extend HasSuspUrl = TeamsMessageId in (suspUrlMsgs)
| summarize Messages=count(), Senders=dcount(SenderEmailAddress), OneToOne=countif(ConvType=="1:1 chat"), GroupChat=countif(ConvType=="Group chat"), ChannelMsgs=countif(ConvType=="Channel"), ThreatMessages=countif(isnotempty(ThreatTypes)), Malware=countif(ThreatTypes has "Malware"), Phish=countif(ThreatTypes has "Phish"), Spam=countif(ThreatTypes has "Spam"), SuspUrlMsgs=countif(HasSuspUrl), FirstSeen=min(Timestamp), LastSeen=max(Timestamp) by SenderDomain
| where ThreatMessages > 0
| extend ThreatRatePct = round(100.0 * ThreatMessages / Messages, 1)
| top 10 by ThreatMessages desc
| project ['Sender Domain']=SenderDomain, Messages, Senders, ['1:1']=OneToOne, ['Group']=GroupChat, ['Channel']=ChannelMsgs, ['Threat Msgs']=ThreatMessages, Malware, Phish, Spam, ['Threat Rate %']=ThreatRatePct, ['Low-Rep URL Msgs']=SuspUrlMsgs, ['First Seen']=FirstSeen, ['Last Seen']=LastSeen

//This query surfaces external sender domains in Microsoft Teams that have NO threat verdict yet but are sending messages with low-reputation URL TLDs or unusual volume, split by conversation type. These are early-warning senders that have not tripped a detection. Messages are de-duplicated to the latest record per message.
// TIP: IsExternalThread may still surface your own accepted domains. To hide them, uncomment the
// ExcludeDomains line below (add your tenant domains) and the matching where-clause.
//let ExcludeDomains = dynamic(["contoso.com","contoso.com"]);
let suspTlds = dynamic(["top","xyz","click","link","shop","online","site","live","icu","cyou","sbs","rest","quest","cfd","bond","buzz","fun","space","monster","work","tk","ml","ga","cf","gq","dev","app","zip","mov","info","win","loan","men","stream","country"]);
let suspUrlMsgs = MessageUrlInfo
    | where isnotempty(UrlDomain)
    | extend Tld = tostring(split(UrlDomain, ".")[-1])
    | where Tld in (suspTlds)
    | distinct TeamsMessageId;
MessageEvents
| summarize arg_max(Timestamp, *) by TeamsMessageId
| where IsExternalThread == true
| extend SenderDomain = tostring(split(SenderEmailAddress, "@")[1])
| where isnotempty(SenderDomain)
//| where SenderDomain !in~ (ExcludeDomains)
| extend ConvType = case(isnotempty(GroupId), "Channel", array_length(todynamic(RecipientDetails)) > 1, "Group chat", "1:1 chat")
| extend HasSuspUrl = TeamsMessageId in (suspUrlMsgs)
| summarize Messages=count(), Senders=dcount(SenderEmailAddress), OneToOne=countif(ConvType=="1:1 chat"), GroupChat=countif(ConvType=="Group chat"), ChannelMsgs=countif(ConvType=="Channel"), ThreatMessages=countif(isnotempty(ThreatTypes)), SuspUrlMsgs=countif(HasSuspUrl), FirstSeen=min(Timestamp), LastSeen=max(Timestamp) by SenderDomain
| where ThreatMessages == 0
| where SuspUrlMsgs > 0 or Messages >= 5
| order by SuspUrlMsgs desc, Messages desc
| take 10
| project ['Sender Domain']=SenderDomain, Messages, Senders, ['1:1']=OneToOne, ['Group']=GroupChat, ['Channel']=ChannelMsgs, ['Low-Rep URL Msgs']=SuspUrlMsgs, ['First Seen']=FirstSeen, ['Last Seen']=LastSeen

//This query shows Microsoft Teams post-delivery ZAP actions by type for the selected period.
MessagePostDeliveryEvents
| summarize Count = count() by ActionType

// Identify MDO-related SecurityIncident IDs via alert correlation
let EmailSecurityIncidents = 
    SecurityIncident
    | mv-expand AlertIds
    | where isnotempty(AlertIds)
    | extend AlertId = tostring(AlertIds)
    | join kind=inner (
        SecurityAlert
        | where ProductName in ("Office 365 Advanced Threat Protection", "Microsoft 365 Defender")
        | extend AlertId = tostring(SystemAlertId)
        | project AlertId
    ) on AlertId
    | distinct ProviderIncidentId;

// Get latest incident state for MDO-related incidents
let LatestMdoIncidents =
    SecurityIncident
    | summarize arg_max(TimeGenerated, Classification, Status, IncidentName) by ProviderIncidentId
    | where ProviderIncidentId in (EmailSecurityIncidents)
    // Exclude other non-email incidents (e.g., DSPM with specific naming pattern)
    | where not(IncidentName startswith "CC_");

// Compute true positive rate among closed MDO incidents
LatestMdoIncidents
| where Status == "Closed"
| summarize
    TruePositiveCount = countif(Classification == "TruePositive"),
    TotalClosed       = count()
| extend TruePositiveRate = iff(
    TotalClosed > 0,
    TruePositiveCount * 100.0 / TotalClosed,
    real(null)
)
